/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void fiq_service_vector (void)__irq
{
  Fiq_Entry * curr ;

  fiq_tc [FIQ_TC_TIMER_1] = T1TC ;
  fiq_tc [FIQ_TC_TIMER_2] = T2TC ;
  fiq_tc [FIQ_TC_TIMER_3] = T3TC ;

  #if DEBUG_FIQ == 1
	gpio_pl_tog(GPIO_PL_LED_GREEN);
  #endif

 for (curr = fiq_list ; curr ; curr = curr->next)
    {
      if(curr->fiq_func)
        {
          curr->fiq_func () ; 

          #ifdef USE_HI_PRI_FIQ
            hi_pri_vec     () ;
          #endif
        }     
    }
#ifdef USE_HI_PRI_FIQ
 hi_pri_vec () ;
#endif

  #if DEBUG_FIQ == 1
	gpio_pl_tog(GPIO_PL_LED_GREEN);
  #endif
  
#ifdef DEV_LPC_236x
   VICVectAddr = 0 ;           // Signal VIC controller we have serviced IRQ
#endif
}

//--------------------------------------------------------------------------//
void void_sentinel (void)
{

}

